 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
PropWriter.prototype.setProperty = function (
	dom,
	name,
	value,
	oldValue,
	isSvg
) {
	let useCapture;
	const svgAlias = attrGuard.svgAlias;
	const eventNames = svgAlias.eventNames;
	const nameSlice = attrGuard.nameSlice;
	const boolMarks = eventNames.boolMarks;

	this.svgMode = isSvg;

	o: if (name === styleConfig.styleName) {
		if (typeof value == 'string') {
			dom.style.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				dom.style.cssText = oldValue = '';
			}

			if (oldValue) {
				for (name in oldValue) {
					if (!(value && name in value)) {
						setStyle(dom.style, name, '', styleConfig.nonDimensional);
					}
				}
			}

			if (value) {
				for (name in value) {
					if (!oldValue || value[name] !== oldValue[name]) {
						setStyle(dom.style, name, value[name], styleConfig.nonDimensional);
					}
				}
			}
		}
	}
	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	else if (name[0] === eventNames.prefix && name[1] === 'n') {
		useCapture =
			name !==
			(name = name.replace(eventNames.capturePattern, nameSlice.captureToken));

		// Infer correct casing for DOM built-in events:
		const lowerName = name.toLowerCase();
		if (
			lowerName in dom ||
			lowerName == 'onfocusin' ||
			lowerName == 'onfocusout'
		)
			name = lowerName.slice(nameSlice.sliceOffset);
		else name = name.slice(nameSlice.sliceOffset);

		if (!dom._listeners) dom._listeners = {};
		dom._listeners[name + useCapture] = value;

